/// Simultaneous connections per route; more are closed at accept.
const MAX_ACTIVE: usize = 64;
const CONNECT_TIMEOUT: Duration = Duration::from_secs(10);

/// Binds every route before returning, so the confined child never races a missing listener.
pub(super) fn start(routes: &[Route]) -> io::Result<()> {
    let mut data = WSADATA::default();
    // SAFETY: version 2.2 and an out structure.
    let error = unsafe { WSAStartup(0x0202, &mut data) };
    if error != 0 {
        return Err(io::Error::from_raw_os_error(error));
    }
    let listeners = routes
        .iter()
        .map(|route| Ok((listener(route)?, route.port)))
        .collect::<io::Result<Vec<_>>>()?;
    for (socket, port) in listeners {
        std::thread::Builder::new()
            .name("broker".into())
            .spawn(move || serve(socket, port))?;
    }
    Ok(())

fn serve(listener: SOCKET, port: u16) {
    let active = Arc::new(AtomicUsize::new(0));
    loop {
        // SAFETY: a listening socket; the peer address is not wanted.
        let client = unsafe { accept(listener, std::ptr::null_mut(), std::ptr::null_mut()) };
        if client == INVALID_SOCKET {
            report(port, &io::Error::last_os_error());
            return;
        }
        // SAFETY: a fresh connected stream socket owned by nobody else; TcpStream only sends, receives and shuts down.
        let client = unsafe { TcpStream::from_raw_socket(client as u64) };
        if active.fetch_add(1, Ordering::SeqCst) >= MAX_ACTIVE {
            active.fetch_sub(1, Ordering::SeqCst);
            continue;
        }
        let active = active.clone();
        let _ = std::thread::Builder::new().name("broker-pair".into()).spawn(move || {
            if let Err(e) = pair(client, port) {
                report(port, &e);
            }
            active.fetch_sub(1, Ordering::SeqCst);
        });

/// Pipes both ways until both directions end; each end's EOF is passed on as a half-close. The sockets are shared,
/// never duplicated: `WSADuplicateSocketW` is not promised for AF_UNIX.
fn pair(client: TcpStream, port: u16) -> io::Result<()> {
    let upstream = Arc::new(TcpStream::connect_timeout(
        &([127, 0, 0, 1], port).into(),
        CONNECT_TIMEOUT,
    )?);
    let client = Arc::new(client);
    let (from, to) = (client.clone(), upstream.clone());
    let forward = std::thread::Builder::new()
        .name("broker-up".into())
        .spawn(move || copy(&from, &to))?;
    copy(&upstream, &client);
    let _ = forward.join();
    Ok(())
}

fn copy(mut from: &TcpStream, mut to: &TcpStream) {
    let mut buffer = [0u8; 16 * 1024];
    loop {
        match from.read(&mut buffer) {
            Ok(0) => break,
            Ok(n) if to.write_all(&buffer[..n]).is_ok() => {}
            _ => {
                let _ = from.shutdown(Shutdown::Both);
                let _ = to.shutdown(Shutdown::Both);
                return;
            }
        }
    }
    let _ = to.shutdown(Shutdown::Write);

pub(super) fn protect(journal: &Path, paths: &[PathBuf], roots: &[PathBuf], sid: &Sid) -> io::Result<Held> {
    fs::create_dir_all(journal)?;
    let _lock = DirLock::acquire(journal)?;
    reconcile(journal)?;
    // SAFETY: GetCurrentProcessId reads only this process's id and cannot fail.
    let pid = unsafe { GetCurrentProcessId() };
    let mut markers = Vec::new();
    let mut pins = Vec::new();
    let mut pinned: HashSet<PathBuf> = HashSet::new();
    let mut seen: HashSet<Identity> = HashSet::new();
    for (index, path) in paths.iter().enumerate() {
        // Dedupe guards that resolve to the same object, so restoration is order-independent and never leaves a file
        // read-only. A missing name has no identity yet and cannot collide with another name.
        if path.exists() {
            match acl::identity(path) {
                Ok(id) if !seen.insert(id) => continue,
                _ => {}
            }
        }
        let hash = hash(path);
        let state = journal.join(format!("g-{hash}.state"));
        if !state.exists() {
            let content = if path.exists() {
                let sddl = acl::capture(path)?;
                acl::protect(path, sid)?;
                format!("E\n{}\n{}", path.display(), sddl)
            } else {
                fs::create_dir(path)?;
                acl::protect(path, sid)?;
                format!("P\n{}\n", path.display())
            };
            write_atomic(&state, &content)?;
        } else {
            // A joining command still strips its own profile to read-only on an already-protected path.
            acl::protect(path, sid)?;
        }
        // Pin every directory from the path up to its write root so the container cannot move a parent aside.
        for ancestor in ancestors_to_root(path, roots) {
            if !pinned.insert(ancestor.clone()) {
                continue;
            }
            if let Ok(handle) = acl::pin(&ancestor) {
                pins.push(handle);
            }
        }
        let marker = journal.join(format!("o-{hash}-{pid}-{index}.own"));
        let file = OpenOptions::new()
            .create(true)
            .truncate(true)
            .read(true)
            .write(true)
            .open(&marker)?;
        lock(&file, false)?;
        markers.push((file, marker));
    }
    Ok(Held { markers, pins })

/// Releases this command's holds, then restores every path no other live holder still protects.
pub(super) fn release(held: Held, journal: &Path) -> io::Result<()> {
    let _lock = DirLock::acquire(journal)?;
    for (file, marker) in held.markers {
        let _ = unlock(&file);
        drop(file);
        let _ = fs::remove_file(&marker);
    }
    // Release the parent pins before restoring, so a placeholder's directory can be removed.
    drop(held.pins);
    reconcile(journal)
}

/// Replays any leftover state: restores or drops every guarded path with no live holder. Idempotent.
pub(super) fn recover(journal: &Path) -> io::Result<()> {
    if !journal.exists() {
        return Ok(());
    }
    let _lock = DirLock::acquire(journal)?;
    reconcile(journal)

if let Ok(mut file) = File::open(&state) {
    let mut text = String::new();
    if file.read_to_string(&mut text).is_ok() {
        let mut parts = text.splitn(3, '\n');
        let kind = parts.next().unwrap_or("");
        let path = parts.next().unwrap_or("");
        let sddl = parts.next().unwrap_or("");
        if !path.is_empty() {
            let target = PathBuf::from(path);
            match kind {
                "E" => {
                    let _ = acl::restore(&target, sddl);
                }
                // Only ever remove the empty placeholder this guard created. If something is inside it, it is
                // host content: leave it and report, never delete it.
                "P" => {
                    if let Err(error) = fs::remove_dir(&target) {
                        let _ = writeln!(
                            io::stderr().lock(),
                            "hugr-omni-supervisor: appcontainer: leaving placeholder {}: {error}",
                            target.display(),
                        );
                    }
                }
                _ => {}
            }
        }
    }
}
let _ = fs::remove_file(&state);
for owner in dead {
    let _ = fs::remove_file(owner);
}

/// Whether a live process still holds the marker's lock. A dead holder's lock is already released by the OS, so this
/// acquires it and reports the marker free.
fn held_by_other(marker: &Path) -> bool {
    let Ok(file) = OpenOptions::new().read(true).write(true).open(marker) else {
        return false;
    };
    match lock(&file, true) {
        Ok(()) => {
            let _ = unlock(&file);
            false
        }
        Err(error) => error.raw_os_error() == Some(ERROR_LOCK_VIOLATION as i32),
    }
}

fn read_names(dir: &Path) -> Vec<(String, PathBuf)> {
    let Ok(entries) = fs::read_dir(dir) else {
        return Vec::new();
    };
    entries
        .flatten()
        .map(|entry| (entry.file_name().to_string_lossy().into_owned(), entry.path()))
        .collect()
}

fn write_atomic(path: &Path, content: &str) -> io::Result<()> {
    let temp = path.with_extension("tmp");
    File::create(&temp)?.write_all(content.as_bytes())?;
    fs::rename(&temp, path)

if request
    .grants
    .iter()
    .map(|g| &g.0)
    .chain(&request.toolchain)
    .chain(request.routes.iter().map(|r| &r.socket))
    .chain(request.guards.iter())
    .chain(request.journal.iter())
    .any(|p| !p.is_absolute())
{
    return Err("every path must be absolute".into());
}
if !request.toolchain.is_empty() {
    let alone = request.grants.is_empty()
        && request.routes.is_empty()
        && request.guards.is_empty()
        && request.journal.is_none()
        && request.app.is_none()
        && request.line.is_none();
    if request.revoke || request.recover || !alone {
        return Err("--toolchain takes no command and no other grant".into());
    }
    return Ok(request);
}
if (!request.guards.is_empty() || request.recover) && request.journal.is_none() {
    return Err("--guard and --recover need --journal".into());
}
if !request.revoke && !request.recover && (request.app.is_none() || request.line.is_none()) {
    return Err("missing --app or --line".into());
}

fn run(request: &Request) -> Result<i32, String> {
    let toolchain = acl::capability(TOOLCHAIN).map_err(|e| format!("capability {TOOLCHAIN}: {e}"))?;
    if !request.toolchain.is_empty() {
        for path in &request.toolchain {
            let _ = acl::apply(path, &toolchain, Grant::Read);
        }
        return Ok(0);
    }
    // Recovery needs no profile: it only restores ACLs captured by an earlier run and removes stale placeholders.
    if request.recover {
        let journal = request.journal.as_deref().unwrap_or_else(|| Path::new(""));
        guard::recover(journal).map_err(|e| format!("recover {}: {e}", journal.display()))?;
        return Ok(0);
    }
    let sid = acl::profile(&request.name).map_err(|e| format!("profile {}: {e}", request.name))?;
    let folders = request
        .routes
        .iter()
        .filter_map(|r| r.socket.parent().map(|p| (p.to_path_buf(), Grant::Write)));
    let grants: Vec<_> = request.grants.iter().cloned().chain(folders).collect();
    if request.revoke {
        for (path, _) in &grants {
            acl::revoke(path, &sid).map_err(|e| format!("revoke {}: {e}", path.display()))?;
        }
        acl::delete(&request.name).map_err(|e| format!("delete profile {}: {e}", request.name))?;
        return Ok(0);
    }
    for (path, grant) in &grants {
        acl::apply(path, &sid, *grant).map_err(|e| format!("grant {grant:?} {}: {e}", path.display()))?;
    }
    broker::start(&request.routes).map_err(|e| format!("broker: {e}"))?;
    // Protection brackets only the launch, and its holds are released whether the command succeeds or fails. A crash
    // between here and release leaves a journal that the next launch (reconciled in `protect`) or `--recover` replays.
    let journal = request.journal.clone();
    let write_roots: Vec<PathBuf> = grants
        .iter()
        .filter(|(_, grant)| matches!(grant, Grant::Write))
        .map(|(path, _)| path.clone())
        .collect();
    let held = match &journal {
        Some(dir) => Some(guard::protect(dir, &request.guards, &write_roots, &sid).map_err(|e| format!("guard: {e}"))?),
        None => None,
    };
    let (app, line) = (
        request.app.as_deref().unwrap_or_default(),
        request.line.as_deref().unwrap_or_default(),
    );
    let code = launch(app, line, &sid, &toolchain).map_err(|e| format!("start {app}: {e}"));
    if let (Some(held), Some(dir)) = (held, &journal) {
        let _ = guard::release(held, dir);
    }
    for route in &request.routes {
        let _ = std::fs::remove_file(&route.socket);
    }
    code

/// Starts `app` confined to the profile, in a new kill-on-close Job, and waits for it.
fn launch(app: &str, line: &str, sid: &acl::Sid, toolchain: &acl::Sid) -> io::Result<i32> {
    let job = super::job::create()?;
    let jobs: [HANDLE; 1] = [job.as_raw_handle()];
    let mut held = [SID_AND_ATTRIBUTES {
        Sid: toolchain.raw(),
        Attributes: ENABLED,
    }];
    let mut capabilities = SECURITY_CAPABILITIES {
        AppContainerSid: sid.raw(),
        Capabilities: held.as_mut_ptr(),
        CapabilityCount: 1,
        ..SECURITY_CAPABILITIES::default()
    };

let mut code = 0u32;
// SAFETY: a live process handle.
let waited = unsafe { WaitForSingleObject(process.as_raw_handle(), INFINITE) };
// SAFETY: a live process handle and an out value.
if waited != 0 || unsafe { GetExitCodeProcess(process.as_raw_handle(), &mut code) } == 0 {
    return Err(io::Error::last_os_error());
}
// Kill any confined descendant the root left behind and wait until the Job is empty before the caller restores
// ACLs — a process still alive could otherwise write a guarded path during the restore window.
super::job::terminate(&job);
for _ in 0..200 {
    if matches!(super::job::active(&job), None | Some(0)) {
        break;
    }
    std::thread::sleep(std::time::Duration::from_millis(25));
}
drop(job);
Ok(code as i32)

#[test]
fn parses_grants_routes_and_the_command() {
    let request = parse(args(&[
        "orchestra-abc",
        "--read",
        r"C:\w",
        "--write",
        r"C:\w\out",
        "--route",
        r"5432=C:\t\0.sock",
        "--app",
        r"C:\pwsh.exe",
        "--line",
        "pwsh -Command x",
    ]))
    .unwrap();
    assert_eq!(request.name, "orchestra-abc");
    assert_eq!(request.grants.len(), 2);
    assert_eq!(request.routes.len(), 1);
    assert_eq!(request.routes[0].port, 5432);
    assert_eq!(request.line.as_deref(), Some("pwsh -Command x"));
    assert!(!request.revoke);

#[test]
fn refuses_relative_paths_bad_names_ports_and_missing_commands() {
    for bad in [
        &["orchestra", "--read", r"w", "--app", "a", "--line", "l"][..],
        &["orchestra", "--toolchain", r"go"],
        &["orchestra", "--toolchain", r"C:\go", "--app", "a", "--line", "l"],
        &["orchestra", "--toolchain", r"C:\go", "--read", r"C:\w"],
        &["orchestra", "--toolchain", r"C:\go", "--revoke"],
        &["orchestra", "--route", r"0=C:\t\0.sock", "--app", "a", "--line", "l"],
        &["orchestra", "--route", r"5432", "--app", "a", "--line", "l"],
        &["bad name", "--app", "a", "--line", "l"],
        &[&"x".repeat(65), "--app", "a", "--line", "l"],
        &["orchestra", "--read", r"C:\w"],
        &["orchestra", "--unknown", "v", "--app", "a", "--line", "l"],
    ] {
        assert!(parse(args(bad)).is_err(), "{bad:?}");
    }
    assert_eq!(
        parse(args(&["orchestra", "--toolchain", r"C:\go"])).unwrap().toolchain,
        [std::path::PathBuf::from(r"C:\go")]
    );
    assert!(
        parse(args(&["orchestra", "--read", r"C:\w", "--revoke"]))
            .unwrap()
            .revoke
    );

